skin:
#s77 .stage{background:linear-gradient(170deg,#fcfbf9,#f7f6f2);color:#13343b}
#s77 .stage::before{content:'';position:absolute;inset:0;background:radial-gradient(44% 36% at 14% 8%,#20808d0e,transparent 60%);pointer-events:none}
#s77 .d-nav{background:#ffffffb8;border:1px solid #e4e7e5;border-radius:11px}
#s77 .d-logo{font-weight:600;color:#1a6b78}
#s77 .d-links span{opacity:.64}#s77 .d-links span:hover{opacity:1;background:#20808d10;border-radius:7px}
#s77 .d-h{letter-spacing:-.01em}
#s77 .d-p{color:#5c7079}
#s77 .d-btn{background:#20808d;color:#fff;border-radius:10px;font-weight:500}
#s77 .d-btn:hover{background:#1a6b78}
#s77 .d-btn.ghost{background:#00000006;color:#1a6b78;border:1px solid #cfdad7}
#s77 .d-input{background:#fff;border:1px solid #dbe2df;color:#13343b;border-radius:999px}
#s77 .d-tog.onn{background:#20808d}
#s77 .d-badge{background:#20808d0e;color:#17646f;border-radius:6px;font-size:10.5px}
#s77 .d-prog{height:3px;background:#13343b10}#s77 .d-prog i{background:#20808d}
#s77 .d-card{background:#fff;border:1px solid #e4e7e5;border-top:2px solid #20808d;border-radius:9px}
